package com.ftk.tpip.catalog.domain.model;
import com.ftk.tpip.shared.SemanticVersion;import java.time.Instant;import java.util.Objects;import java.util.regex.Pattern;
public record CanonicalContractVersion(Long id,long contractId,int versionNo,SemanticVersion semanticVersion,SchemaStandard schemaStandard,String schemaDocument,String exampleDocument,CompatibilityMode compatibilityMode,String contentChecksum,CanonicalContractLifecycleStatus lifecycleStatus,Instant publishedAt,Instant createdAt){private static final Pattern SHA=Pattern.compile("^[a-f0-9]{64}$");public CanonicalContractVersion{if(id!=null&&id<=0)throw new IllegalArgumentException("id must be positive");if(contractId<=0)throw new IllegalArgumentException("contractId must be positive");if(versionNo<0)throw new IllegalArgumentException("versionNo must not be negative");semanticVersion=Objects.requireNonNull(semanticVersion);schemaStandard=Objects.requireNonNull(schemaStandard);if(schemaDocument==null||schemaDocument.isBlank())throw new IllegalArgumentException("schemaDocument must not be blank");compatibilityMode=Objects.requireNonNull(compatibilityMode);if(contentChecksum==null||!SHA.matcher(contentChecksum).matches())throw new IllegalArgumentException("contentChecksum must be a lowercase SHA-256 value");lifecycleStatus=Objects.requireNonNull(lifecycleStatus);if(lifecycleStatus==CanonicalContractLifecycleStatus.PUBLISHED&&publishedAt==null)throw new IllegalArgumentException("published version must have publishedAt");}public static CanonicalContractVersion draft(long contractId,SemanticVersion semver,SchemaStandard standard,String schema,String example,CompatibilityMode mode,String checksum){return new CanonicalContractVersion(null,contractId,0,semver,standard,schema,example,mode,checksum,CanonicalContractLifecycleStatus.DRAFT,null,null);}}
